import type { ReactElement, ReactNode } from "react";
import { ExternalLink } from "lucide-react";
import { Badge } from "../../components/ui/badge";
import { Card } from "../../components/ui/card";
import type { DetailImage, StageVisuals } from "../projectDetailContent";
import type { ProjectSubDetail } from "../types";

// 역할 문장에서 맡은 범위를 나타내는 단어만 굵게 표시한다.
function emphasizeContribution(role: string): ReactNode[] {
  return role.split(/(단독|공동|주도|담당|참여|일부)/).map((part, index) =>
    index % 2 === 1 ? (
      <strong className="font-semibold text-foreground" key={index}>
        {part}
      </strong>
    ) : (
      part
    ),
  );
}

// 모달 본문: 결과 → 역할·기술 스택 → 문제 → 해결한 일 → 화면 순서로, 성과를 가장 먼저 보여 준다.
export function ImpactDetailBlock({
  subDetail,
  visuals,
  demo,
  images,
  mediaLabel = "화면",
  mediaBadge,
}: {
  subDetail: ProjectSubDetail;
  visuals?: StageVisuals;
  demo?: ReactNode;
  images?: DetailImage[];
  mediaLabel?: string;
  mediaBadge?: string;
}): ReactElement {
  // 문제·해결과 같은 "제목 위, 내용 아래" 구조로 읽는 방향을 맞춘다.
  const meta = (
    <dl className="m-0 mt-7 grid gap-x-8 gap-y-7 break-keep text-body-md text-ink-secondary md:grid-cols-2">
      <div>
        <dt className="text-title text-foreground">역할</dt>
        <dd className="m-0 mt-2">{emphasizeContribution(subDetail.role)}</dd>
      </div>
      {subDetail.techStack && subDetail.techStack.length > 0 && (
        <div>
          <dt className="text-title text-foreground">기술 스택</dt>
          <dd className="m-0 mt-2 flex flex-wrap gap-1.5">
            {subDetail.techStack.map((tech) => (
              <Badge variant="muted" className="bg-surface-strong" key={tech}>
                {tech}
              </Badge>
            ))}
          </dd>
        </div>
      )}
    </dl>
  );

  // 수치 앞에 무엇의 수치인지 붙여, 수치 아래 부가 설명 없이 한 번에 읽히게 한다.
  const resultCard = (
    <Card
      role="group"
      aria-label="결과"
      className="border-transparent bg-[color:var(--accent-soft)] p-5 [--result-line:color-mix(in_srgb,var(--accent-strong)_25%,transparent)] md:p-6"
    >
      {subDetail.highlights.length > 0 && (
        <dl className="mb-4 grid divide-y divide-[color:var(--result-line)] border-b border-[color:var(--result-line)] pb-4 md:grid-flow-col md:auto-cols-fr md:divide-x md:divide-y-0">
          {subDetail.highlights.map((highlight) => (
            <div
              className={`flex gap-y-0.5 py-2.5 first:pt-0 last:pb-0 md:px-4 md:py-0 md:first:pl-0 md:last:pr-0 ${
                subDetail.highlights.length >= 3 ? "flex-col" : "flex-wrap items-baseline gap-x-2"
              }`}
              key={highlight.label}
            >
              <dt className="break-keep text-[22px] font-bold leading-tight tracking-[-0.5px] text-foreground md:text-[24px]">{highlight.label}</dt>
              <dd className="text-[22px] font-bold leading-tight tracking-[-0.5px] text-[color:var(--accent-strong)] md:text-[24px]">
                {highlight.value}
              </dd>
            </div>
          ))}
        </dl>
      )}
      <p className="whitespace-pre-line break-keep text-body-md text-foreground">{subDetail.result}</p>
    </Card>
  );

  return (
    <section aria-label={`${subDetail.number} ${subDetail.title}`}>
      {resultCard}
      {meta}

      <div className="mt-7">
        <h3 className="text-title text-foreground">문제</h3>
        <p className="mt-2 whitespace-pre-line break-keep text-body-md text-ink-secondary">{subDetail.background}</p>
        {subDetail.backgroundIssues && (
          <ul className="mt-2 list-disc space-y-1 pl-5 text-body-md text-ink-secondary [&_b]:font-semibold [&_b]:text-foreground">
            {subDetail.backgroundIssues.map((issue) => (
              <li className="break-keep" key={issue}>
                {issue}
              </li>
            ))}
          </ul>
        )}
        {visuals?.background && <div className="sub-detail-visual mt-4">{visuals.background}</div>}
      </div>

      <div className="mt-8 border-t border-border pt-7">
        <h3 className="text-title text-foreground">해결</h3>
        {visuals?.solution && <div className="sub-detail-visual mt-4">{visuals.solution}</div>}
        <div className="mt-6 space-y-7">
          {subDetail.tasks.map((group) => {
            const visual = visuals?.tasks?.[group.title];
            return (
              <div key={group.title}>
                <h4 className="break-keep text-body-md font-bold text-foreground">{group.title}</h4>
                <ul className="mt-2 list-disc space-y-1.5 pl-5 text-body-md text-ink-secondary [&_b]:font-semibold [&_b]:text-foreground">
                  {group.items.map((item) => (
                    <li className="break-keep" key={item}>
                      {item}
                    </li>
                  ))}
                </ul>
                {visual && <div className="sub-detail-visual mt-4">{visual}</div>}
              </div>
            );
          })}
        </div>
        {subDetail.blogLinks && subDetail.blogLinks.length > 0 && (
          <p className="mt-6 flex flex-wrap items-center gap-x-4 gap-y-1 text-caption">
            <span className="text-muted">관련 글</span>
            {subDetail.blogLinks.map((link) => (
              <a
                key={link.href}
                className="inline-flex items-center gap-1 text-accent underline underline-offset-2"
                href={link.href}
                target="_blank"
                rel="noreferrer"
              >
                {link.label} <ExternalLink size={13} aria-hidden="true" />
              </a>
            ))}
          </p>
        )}
      </div>

      {(Boolean(images?.length) || Boolean(demo)) && (
        <div className="mt-8 grid min-w-0 gap-4 border-t border-border pt-7">
          <p className="flex items-center gap-2 text-title">
            {mediaLabel}
            {mediaBadge && <Badge variant="primary">{mediaBadge}</Badge>}
          </p>
          {images?.map((image) => (
            <figure className="m-0" key={image.src}>
              <img className="block w-full rounded-lg border border-border" src={image.src} alt={image.alt} loading="lazy" />
              {image.caption && <figcaption className="mt-2 break-keep text-caption text-muted">{image.caption}</figcaption>}
            </figure>
          ))}
          {demo && <div className="library-detail-demo">{demo}</div>}
        </div>
      )}
    </section>
  );
}
