import type { ReactElement, ReactNode } from "react";
import { ArrowDown, ArrowRight } from "lucide-react";

const linkageSteps = ["어댑터", "인터페이스 정책", "서비스 정책", "커넥터"];

function Next(): ReactElement {
  return (
    <span className="flex items-center justify-center text-subtle" aria-hidden="true">
      <ArrowRight className="hidden md:block" size={16} />
      <ArrowDown className="md:hidden" size={16} />
    </span>
  );
}

function SharedStage({ title }: { title: string }): ReactElement {
  return (
    <div className="flex flex-col justify-center rounded-md border border-border bg-background p-3">
      <span className="break-keep text-body-sm font-bold text-foreground">{title}</span>
      <span className="text-caption text-muted">4단계 · 동일</span>
    </div>
  );
}

function ProcessRow({ title, count, accent = false, children }: { title: string; count: string; accent?: boolean; children: ReactNode }): ReactElement {
  return (
    <div className="grid gap-2">
      <p className={`m-0 flex flex-wrap items-baseline gap-x-2 text-body-sm font-bold ${accent ? "text-[color:var(--accent-strong)]" : "text-foreground"}`}>
        {title}
        <span className="text-title">{count}</span>
      </p>
      <div className="grid gap-1 md:grid-cols-[120px_auto_minmax(0,1fr)_auto_120px] md:gap-2">
        <SharedStage title="모델 등록 등" />
        <Next />
        {children}
        <Next />
        <SharedStage title="매핑 등" />
      </div>
    </div>
  );
}

// 앞뒤 단계는 그대로이고, 가운데 연계 정보 등록만 달라진다는 것을 위아래 비교로 보여 준다.
export function AdapterWizardProcessDiagram(): ReactElement {
  return (
    <figure className="m-0 grid gap-4 rounded-[10px] border border-border bg-surface p-4" aria-label="거래 등록 절차에서 연계 정보 등록 구간의 개선 전후 비교">
      <ProcessRow title="기존 · 화면을 하나씩 열어 등록" count="12단계">
        <ol className="m-0 grid list-none grid-cols-2 gap-2 p-0 sm:grid-cols-4">
          {linkageSteps.map((step) => (
            <li className="flex items-center justify-center break-keep rounded-md border border-dashed border-subtle p-3 pl-3 text-center text-body-sm text-foreground before:content-none" key={step}>
              {step}
            </li>
          ))}
        </ol>
      </ProcessRow>
      <ProcessRow title="개선 · 위자드 하나에서 등록" count="9단계" accent>
        <div className="grid content-center gap-1 rounded-md border border-[color:var(--accent-strong)] bg-[color:var(--accent-soft)] p-3 text-center text-[color:var(--accent-strong)]">
          <span className="break-keep text-body-md font-bold">연계 정보 등록 위자드</span>
          <span className="break-keep text-caption">{linkageSteps.join(" · ")}을 한 번에 저장</span>
        </div>
      </ProcessRow>
    </figure>
  );
}
