import { Fragment, type ReactElement } from "react";
import { ArrowRight, Hand, Zap } from "lucide-react";

const before = ["버전 결정", "빌드", "Nexus 배포"];
const after = ["커밋 메시지 검사", "빌드", "버전 결정", "Nexus 배포"];

function StageRow({ stages, automated }: { stages: string[]; automated: boolean }): ReactElement {
  return (
    <ol className="m-0 flex list-none items-stretch gap-1 p-0 sm:gap-2">
      {stages.map((stage, index) => (
        <Fragment key={stage}>
          <li
            className={`flex min-w-0 flex-1 items-center justify-center break-keep rounded-md border p-2 pl-2 text-center text-caption font-bold before:content-none sm:p-3 sm:text-body-sm ${
              automated
                ? "border-[color:var(--accent-strong)] bg-[color:var(--accent-soft)] text-[color:var(--accent-strong)]"
                : "border-border bg-background text-foreground"
            }`}
          >
            {stage}
          </li>
          {index < stages.length - 1 && (
            <ArrowRight className="w-3 shrink-0 self-center text-subtle sm:w-4" size={16} aria-hidden="true" />
          )}
        </Fragment>
      ))}
    </ol>
  );
}

// 어드민 빌드(수동 1번 실행)와 달리, master push 이후에는 사람이 개입하지 않는다는 것을 보여 준다.
export function ReleasePipelineDiagram(): ReactElement {
  return (
    <figure className="m-0 grid gap-4 rounded-[10px] border border-border bg-surface p-4" aria-label="공통 라이브러리 릴리스 절차의 자동화 전후 비교">
      <div className="grid gap-2">
        <p className="m-0 flex flex-wrap items-center gap-1.5 break-keep text-body-sm font-bold text-foreground">
          <Hand size={15} aria-hidden="true" />
          기존 · 릴리스마다 개발자가 직접 실행
        </p>
        <StageRow stages={before} automated={false} />
      </div>
      <div className="grid gap-2">
        <p className="m-0 flex flex-wrap items-center gap-1.5 break-keep text-body-sm font-bold text-[color:var(--accent-strong)]">
          <Zap size={15} aria-hidden="true" />
          개선 · master push 후 전부 자동
        </p>
        <StageRow stages={after} automated />
      </div>
    </figure>
  );
}
