import { Fragment, type ReactElement } from "react";
import { ArrowRight, Hand, Zap } from "lucide-react";

type Stage = { work: string; actor: string };

const before: Stage[] = [
  { work: "프론트 빌드", actor: "개발자 PC" },
  { work: "번들 반영", actor: "개발자 커밋" },
  { work: "WAR 빌드·개발 서버 전달", actor: "개발자가 Jenkins 실행" },
];

const after: Stage[] = before.map(({ work }) => ({ work, actor: "Jenkins 자동" }));

const gridClass = "grid grid-cols-[1fr_auto_1fr_auto_1fr] items-stretch gap-1 sm:gap-2";

function StageRow({ stages, automated }: { stages: Stage[]; automated: boolean }): ReactElement {
  return (
    <ol className={`${gridClass} m-0 list-none p-0`}>
      {stages.map((stage, index) => (
        <Fragment key={stage.work}>
          <li
            className={`flex min-w-0 flex-col justify-center gap-0.5 rounded-md border p-2 pl-2 before:content-none sm:p-3 ${
              automated
                ? "border-[color:var(--accent-strong)] bg-[color:var(--accent-soft)] text-[color:var(--accent-strong)]"
                : "border-border bg-background text-foreground"
            }`}
          >
            <span className="break-keep text-caption font-bold sm:text-body-sm">{stage.work}</span>
            <span className="break-keep text-[11px] leading-tight sm:text-caption">{stage.actor}</span>
          </li>
          {index < stages.length - 1 && (
            <ArrowRight className="w-3 shrink-0 self-center text-subtle sm:w-4" size={16} aria-hidden="true" />
          )}
        </Fragment>
      ))}
    </ol>
  );
}

// 같은 작업을 위아래로 맞춰, 달라진 것이 "누가 실행하는가"임을 바로 읽게 한다.
export function BuildPipelineDiagram(): ReactElement {
  return (
    <figure className="m-0 grid gap-4 rounded-[10px] border border-border bg-surface p-4" aria-label="어드민 빌드 절차의 자동화 전후 비교">
      <div className="grid gap-2">
        <p className="m-0 flex flex-wrap items-center gap-1.5 text-body-sm font-bold text-foreground">
          <Hand size={15} aria-hidden="true" />
          기존 · 개발자가 단계마다 직접 실행
          <span className="font-semibold text-muted">(수동 3번)</span>
        </p>
        <StageRow stages={before} automated={false} />
      </div>
      <div className="grid gap-2">
        <p className="m-0 flex flex-wrap items-center gap-1.5 text-body-sm font-bold text-[color:var(--accent-strong)]">
          <Zap size={15} aria-hidden="true" />
          개선 · 개발자는 Job만 실행
          <span className="font-semibold">(수동 1번)</span>
        </p>
        <StageRow stages={after} automated />
      </div>
      <figcaption className="break-keep text-caption text-muted">개발 서버 재기동은 이 파이프라인과 별도로 진행</figcaption>
    </figure>
  );
}
